 private val i get()=InstrumentationRegistry.getInstrumentation()
 private fun result(refuse:Boolean=false,f:(PromiseImpl)->Unit):String {val latch=CountDownLatch(1);var value="";var failed=false;f(PromiseImpl(Callback{v->value=v[0]?.toString()?:"null";latch.countDown()},Callback{v->failed=true;value=v[0]?.toString()?:"Rejected";latch.countDown()}));assertTrue(latch.await(60,TimeUnit.SECONDS));assertEquals(value,refuse,failed);return value}
 private fun js(code:String):String {val latch=CountDownLatch(1);var value="null";i.runOnMainSync {fun find(v:View):WebView?{if(v is WebView)return v;if(v is ViewGroup)for(n in v.childCount-1 downTo 0){val w=find(v.getChildAt(n));if(w!=null)return w};return null};val web=android.view.inspector.WindowInspector.getGlobalWindowViews().asReversed().firstNotNullOfOrNull{find(it)}?:error("Reader WebView absent");web.evaluateJavascript(code){value=it;latch.countDown()}};assertTrue(latch.await(10,TimeUnit.SECONDS));return value}
 private fun touch(selector:String,long:Boolean=false):Double {Thread.sleep(350);val latch=CountDownLatch(1);var x=0;var y=0;var top=0.0;i.runOnMainSync{fun find(v:View):WebView?{if(v is WebView)return v;if(v is ViewGroup)for(n in v.childCount-1 downTo 0){val w=find(v.getChildAt(n));if(w!=null)return w};return null};val web=android.view.inspector.WindowInspector.getGlobalWindowViews().asReversed().firstNotNullOfOrNull{find(it)}?:error("WebView absent");val origin=IntArray(2);web.getLocationOnScreen(origin);val scale=web.resources.displayMetrics.density;web.evaluateJavascript("(()=>{const e=document.querySelector("+JSONObject.quote(selector)+");if(!e)return null;e.scrollIntoView({block:'center'});let r=e.getBoundingClientRect();if("+long+"){const n=document.createTreeWalker(e,NodeFilter.SHOW_TEXT).nextNode();const a=document.createRange();a.setStart(n,0);a.setEnd(n,Math.min(5,n.length));r=a.getBoundingClientRect()}return {x:r.left+r.width/2,y:r.top+r.height/2,scroll:window.scrollY}})()"){v->if(v!="null"){val p=JSONObject(v);top=p.getDouble("scroll");x=origin[0]+(p.getDouble("x")*scale).toInt();y=origin[1]+(p.getDouble("y")*scale).toInt()};latch.countDown()}};assertTrue(latch.await(10,TimeUnit.SECONDS));assertTrue("Touch target absent",x>0&&y>0);Thread.sleep(250);if(long)UiDevice.getInstance(i).swipe(x,y,x,y,150)else UiDevice.getInstance(i).click(x,y);return top}
 private fun tap(node:UiObject2){val p=node.visibleCenter;UiDevice.getInstance(i).swipe(p.x,p.y,p.x,p.y,12);Thread.sleep(180)}
 private fun waitJs(expression:String){for(n in 0..40){if(js(expression)=="true")return;Thread.sleep(250)};fail("Reader assertion failed: "+expression)}
 private fun options(d:UiDevice,label:String){assertTrue("Previous sheet still owns focus",d.wait(Until.gone(By.desc("Done")),5000));assertTrue("Find bar still owns focus",d.wait(Until.gone(By.desc("Close find")),5000));val trigger=d.findObjects(By.desc("Reading options")).firstOrNull{it.visibleBounds.top<500}?:error("Reading header absent");tap(trigger);assertTrue("Reading option absent: "+label,d.wait(Until.hasObject(By.desc(label)),5000));tap(d.findObject(By.desc(label)))}
 @Test fun presentationAndPdfNative(){require(android.os.Build.HARDWARE=="ranchu");val ctx=BridgeReactContext(i.targetContext);val module=VaultorModule(ctx);val args=InstrumentationRegistry.getArguments();val bootstrap=JSONObject(result{module.storage("bootstrap","{}",it)});val host=bootstrap.getString("selected");val profiles=bootstrap.getJSONArray("profiles");require((0 until profiles.length()).map{profiles.getJSONObject(it)}.first{it.getString("hostId")==host}.getString("address").startsWith("https://127.0.0.1:"));val active=JSONObject(result{module.activate(host,it)});val epoch=active.getString("epoch");val identity=JSONObject(JSONObject(result{module.apiFor(host,epoch,"/workspace/identity","GET",null,null,it)}).getString("body"));val scope=JSONArray().put(host).put(identity.getString("id")).put(identity.getString("generation")).toString();val media=JSONObject().put("hostId",host).put("epoch",epoch).put("scope",scope).put("mime","application/pdf").put("resourceId",args.getString("pdfId")).put("page",7).put("renderScale",2)
 val pdf=JSONObject(result{module.media("preview",media.toString(),it)});assertEquals(12,pdf.getInt("pages"));assertEquals(7,pdf.getInt("page"));assertEquals(1200,pdf.getInt("width"));assertEquals(1800,pdf.getInt("height"));assertTrue(File(android.net.Uri.parse(pdf.getString("uri")).path!!).exists());media.put("resourceId",args.getString("lockedId"));assertTrue(result(true){module.media("preview",media.toString(),it)}.contains("Password-protected"));media.put("resourceId",args.getString("imageId")).put("mime","image/png");val image=JSONObject(result{module.media("preview",media.toString(),it)});assertEquals(1600,image.getInt("originalWidth"));assertEquals(1000,image.getInt("height"));
 val before=result{module.readerPreferences("get","{}",it)};try{result{module.readerPreferences("put","{\"theme\":\"oled\",\"accent\":\"mint\",\"size\":80,\"spacing\":1,\"measure\":900}",it)};val stored=JSONObject(result{VaultorModule(ctx).readerPreferences("get","{}",it)});assertEquals("oled",stored.getString("theme"));assertEquals(28.0,stored.getDouble("size"),0.0);assertEquals(1.4,stored.getDouble("spacing"),0.0);result(true){module.openExternal("javascript:alert(1)",it)};result(true){module.openExternal("https://user:password@example.com",it)};}finally{result{module.readerPreferences("put",before,it)}}
 val key=JSONObject().put("scope",scope).put("resourceId",args.getString("pdfId")).put("page",7).put("zoom",2).put("x",20).put("y",30);result{module.readerMediaPosition("put",key.toString(),it)};assertEquals(7,JSONObject(result{VaultorModule(ctx).readerMediaPosition("get",key.toString(),it)}).getInt("page"));val wrong=JSONObject(key.toString()).put("scope",JSONArray().put(host).put("other-workspace").put("other-generation").toString());assertEquals("{}",result{module.readerMediaPosition("get",wrong.toString(),it)});
 }
 @Test fun richReaderInteraction(){val d=UiDevice.getInstance(i);val args=InstrumentationRegistry.getArguments();i.targetContext.startActivity(i.targetContext.packageManager.getLaunchIntentForPackage("com.vaultor.app")!!.addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));assertTrue(d.wait(Until.hasObject(By.desc("Open navigation").enabled(true)),30000));tap(d.findObject(By.desc("Open navigation")));assertTrue(d.wait(Until.hasObject(By.desc("Library")),5000));tap(d.findObject(By.desc("Library")));assertTrue(d.wait(Until.hasObject(By.descContains("R2 Rich reading")),15000));tap(d.findObject(By.descContains("R2 Rich reading")));assertTrue(d.wait(Until.hasObject(By.desc("Reading options")),15000));waitJs("!!document.querySelector('#heading-0')");assertEquals("0",js("document.querySelectorAll('[contenteditable],input').length"));
