 options(d,"Find within note");assertTrue(d.wait(Until.hasObject(By.desc("Find within note")),5000));d.findObject(By.desc("Find within note")).text="across bold marks";Thread.sleep(1000);assertTrue(d.hasObject(By.desc("Next match")));assertEquals("1",js("CSS.highlights.get('matches').size"));tap(d.findObject(By.desc("Close find")));
