 touch("button[data-resource-id='"+args.getString("imageId")+"']");assertTrue(d.wait(Until.hasObject(By.desc("Next image")),15000));waitJs("document.querySelector('#image').naturalWidth===1600");tap(d.findObject(By.desc("Zoom in")));Thread.sleep(300);tap(d.findObject(By.desc("Fit")));tap(d.findObject(By.desc("Next image")));assertTrue(d.wait(Until.hasObject(By.textContains("2 / 2")),10000));waitJs("document.querySelector('#image').naturalWidth===1600");d.takeScreenshot(File(i.targetContext.getExternalFilesDir(null),"r2-image.png"));val imageObject=d.findObject(By.clazz("android.widget.Image").desc("image-2.png")) ?: d.findObject(By.clazz("android.widget.Image").text("image-2.png"));assertNotNull("Image gesture target absent",imageObject);imageObject.pinchOpen(0.5f);Thread.sleep(500);waitJs("Number(document.querySelector('#image').style.width.replace('px',''))>innerWidth");tap(d.findObject(By.desc("Fit")));Thread.sleep(300);imageObject.swipe(Direction.RIGHT,0.6f);assertTrue("Image swipe did not navigate",d.wait(Until.hasObject(By.textContains("1 / 2")),10000));d.pressBack();assertTrue("Reader did not return after preview",d.wait(Until.hasObject(By.desc("Reading options")),5000));
 touch("a[href^='https:']");assertTrue(d.wait(Until.hasObject(By.text("Open external link?")),5000));tap(d.findObject(By.text(java.util.regex.Pattern.compile("(?i)^cancel$"))));assertTrue(d.wait(Until.hasObject(By.desc("Reading options")),5000));
 options(d,"Reading appearance");tap(d.findObject(By.desc("Light")));tap(d.findObject(By.desc("Done")));waitJs("getComputedStyle(document.body).backgroundColor==='rgb(250, 250, 250)'");d.takeScreenshot(File(i.targetContext.getExternalFilesDir(null),"r2-reading-light.png"));d.setOrientationLeft();Thread.sleep(700);waitJs("document.body.scrollWidth<=innerWidth+2");d.takeScreenshot(File(i.targetContext.getExternalFilesDir(null),"r2-reading-landscape.png"));d.setOrientationNatural();Thread.sleep(500);
