 @Test fun journeysAndColdRestoreSeed(){val d=UiDevice.getInstance(i);i.targetContext.startActivity(i.targetContext.packageManager.getLaunchIntentForPackage("com.vaultor.app")!!.addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));assertTrue(d.wait(Until.hasObject(By.desc("Open navigation").enabled(true)),30000));tap(d.findObject(By.desc("Open navigation")));assertTrue(d.wait(Until.hasObject(By.desc("Library")),5000));tap(d.findObject(By.desc("Library")));assertTrue(d.wait(Until.hasObject(By.descContains("R2 Rich reading")),15000));tap(d.findObject(By.descContains("R2 Rich reading")));waitJs("!!document.querySelector('#heading-0')");touch("a.resource[aria-label^='A3 Linked fixture']");waitJs("document.body.textContent.includes('Emulator editing fixture')");touch("a.resource");assertTrue(d.wait(Until.hasObject(By.text("A1 Editor fixture")),15000));waitJs("document.querySelector('a.resource').textContent==='A3 Linked fixture'");touch("a.resource");assertTrue(d.wait(Until.hasObject(By.text("A3 Linked fixture")),15000));Thread.sleep(600);options(d,"Reading journey");assertTrue(d.wait(Until.hasObject(By.textContains("4. A3 Linked fixture")),5000));d.pressBack();assertTrue(d.wait(Until.gone(By.text("Reading journey")),5000));Thread.sleep(250);d.pressBack();assertTrue(d.wait(Until.hasObject(By.text("A1 Editor fixture")),15000));Thread.sleep(250);d.pressBack();assertTrue(d.wait(Until.hasObject(By.text("A3 Linked fixture")),15000));Thread.sleep(250);d.pressBack();assertTrue(d.wait(Until.hasObject(By.text("R2 Rich reading")),15000));waitJs("!!document.querySelector('#heading-0')");Thread.sleep(700);waitJs("(()=>{const a=[...document.querySelectorAll('a.resource')].find(a=>a.textContent==='A3 Linked fixture');const r=a.getBoundingClientRect();return r.top>-30&&r.bottom<innerHeight+30})()");
 options(d,"Note outline");tap(d.findObject(By.textContains("The end")));Thread.sleep(600);d.pressHome();Thread.sleep(400);i.targetContext.startActivity(i.targetContext.packageManager.getLaunchIntentForPackage("com.vaultor.app")!!.addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));assertTrue(d.wait(Until.hasObject(By.desc("Reading options")),15000));waitJs("window.scrollY>2000");val bootstrap=JSONObject(result{VaultorModule(BridgeReactContext(i.targetContext)).storage("bootstrap","{}",it)});val host=bootstrap.getString("selected");val sessions=bootstrap.getJSONObject("sessions");val session=sessions.keys().asSequence().map{sessions.getJSONObject(it)}.filter{it.getString("hostId")==host}.maxBy{it.optLong("at")};File(i.targetContext.noBackupFilesDir,"r2-reading-restore.json").writeText(session.getJSONObject("position").toString());
