 @Test fun themesAndMotion(){val d=UiDevice.getInstance(i);i.targetContext.startActivity(i.targetContext.packageManager.getLaunchIntentForPackage("com.vaultor.app")!!.addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));assertTrue(d.wait(Until.hasObject(By.desc("Reading options")),30000));waitJs("!!document.querySelector('p')");js("window.r2RetainedParagraph=document.querySelector('p');true");options(d,"Reading appearance");tap(d.findObject(By.desc("Dark")));tap(d.findObject(By.desc("Done")));waitJs("getComputedStyle(document.body).backgroundColor==='rgb(16, 17, 20)'");d.takeScreenshot(File(i.targetContext.getExternalFilesDir(null),"r2-reading-dark.png"));options(d,"Reading appearance");tap(d.findObject(By.desc("OS")));tap(d.findObject(By.desc("Done")));val night=d.executeShellCommand("cmd uimode night").substringAfter(":").trim();val motion=d.executeShellCommand("settings get global transition_animation_scale").trim();try{d.executeShellCommand("cmd uimode night no");waitJs("document.documentElement.dataset.theme==='light'");d.executeShellCommand("cmd uimode night yes");waitJs("document.documentElement.dataset.theme==='dark'");waitJs("window.r2RetainedParagraph===document.querySelector('p')");d.executeShellCommand("settings put global transition_animation_scale 0");waitJs("document.documentElement.dataset.motion==='snappy'");d.executeShellCommand("settings put global transition_animation_scale 1");waitJs("document.documentElement.dataset.motion==='smooth'");}finally{if(night in listOf("yes","no","auto"))d.executeShellCommand("cmd uimode night "+night);if(motion=="null")d.executeShellCommand("settings delete global transition_animation_scale")else d.executeShellCommand("settings put global transition_animation_scale "+motion)}}

